'use strict';

// P1 (feat/p1-mtf-entries), the arms : arm D, today's, is byte-identical to the base (feat/mtf-structure
// d48538434): the MTF read's record at every bar of the four real fixtures, every side, digests to the base module's own
// (generated by running d48538434's mtf-structure.js on the same inputs; a deliberate change to today's record regenerates
// it and is explained like a golden). An MTF arm's record differs (its mode); arm D's briefing and lines are tested in
// mtf-entry-briefing.test.js, its compose checks in composed-reads-mtf.test.js, its gate verdicts by the goldens.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const crypto = require('crypto');
const M = require('../../scripts/lib/trading/mtf-structure');
const ME = require('../../scripts/lib/trading/mtf-entry');
const GF = require('../../scripts/lib/eval/goal-fixture');

const AN = require('../../scripts/lib/tunables').analysis();
const CFG = AN.mtfStructure;
const BASE_DIGEST = 'a7cdd834639536ef11e41fe6e717a2dc44e09aac51ad2544841af844a318915c'; // d48538434, 52,800 records
const FX = path.join(__dirname, '..', 'fixtures', 'mtf-structure');
const opts = { tick: 0.25, bufferTicks: 1, equalAtr: AN.marketState.equalAtr, k: AN.indicators.swingK, depth: CFG.depth, sideMode: 'rule', warmBars: CFG.warmBars, hierarchy: CFG.hierarchy };

function digest(extra = {}) {
  const h = crypto.createHash('sha256');
  let n = 0;
  for (const d of ['2022-03-07', '2022-04-11', '2022-04-25', '2022-07-12']) {
    const bars = GF.decodeBars(JSON.parse(zlib.gunzipSync(fs.readFileSync(path.join(FX, `${d}.json.gz`)))).bars);
    for (const side of ['long', 'short', null]) for (const r of M.recordsOf({ ...opts, bars, minutes: 3, levels: M.levelsOf(CFG), side, ...extra })) { h.update(JSON.stringify(r)); n += 1; }
  }
  return { n, hex: h.digest('hex') };
}

test('arm D: the MTF record at every bar of the real fixtures is byte-identical to the base\'s (no early tracking, no rank, no context)', () => {
  const d = digest();
  assert.equal(d.n, 52800);
  assert.equal(d.hex, BASE_DIGEST);
});

test('an MTF arm\'s record is not today\'s (its mode, rank, context): the digest differs', () => {
  const mode = ME.recordMode(ME.modeOf({ arm: 'A', exitMode: 'trail', minStage: 'potential' }, {}, { isReplay: () => true }));
  assert.notEqual(digest({ mode, sideMode: 'parent' }).hex, BASE_DIGEST);
});
